  const tier = h.byLabel("回答档位"); tier.value = "pro"; tier.fire("change");
  const image = new Blob(["retained-file"], { type: "image/png" }); image.name = "下一轮图片.png";
  h.byLabel("选择图片文件").files = [image]; h.byLabel("选择图片文件").fire("change"); await flush();
